=== PriceList.java
import java.math.BigDecimal;
import java.util.Map;
import java.util.Set;

/**
 * The MHPCO price list: the base premium each kind of item is tariffed at.
 *
 * <p>The MHPCO tariffs main items individually and components as a category:
 * every component carries the same base premium, whatever it is made of.
 *
 * <p>Changes whenever the MHPCO revises its tariff or takes on a new kind of
 * item; knows nothing about how a premium is assembled from those amounts.
 */
final class PriceList {

    private static final int SWORD_BASE_PREMIUM_IN_G = 100;
    private static final int AMULET_BASE_PREMIUM_IN_G = 60;
    private static final int STAFF_BASE_PREMIUM_IN_G = 80;
    private static final int POTION_BASE_PREMIUM_IN_G = 40;

    private static final int COMPONENT_BASE_PREMIUM_IN_G = 25;

    private static final int NOT_TARIFFED = 0;

    private static final int SWORD_INSURANCE_VALUE_IN_G = 1000;
    private static final int AMULET_INSURANCE_VALUE_IN_G = 600;
    private static final int STAFF_INSURANCE_VALUE_IN_G = 800;
    private static final int POTION_INSURANCE_VALUE_IN_G = 400;
    private static final int COMPONENT_INSURANCE_VALUE_IN_G = 250;

    private static final Map<String, Integer> MAIN_ITEM_INSURANCE_VALUES_IN_G = Map.of(
            "sword", SWORD_INSURANCE_VALUE_IN_G,
            "amulet", AMULET_INSURANCE_VALUE_IN_G,
            "staff", STAFF_INSURANCE_VALUE_IN_G,
            "potion", POTION_INSURANCE_VALUE_IN_G);

    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUMS_IN_G = Map.of(
            "sword", SWORD_BASE_PREMIUM_IN_G,
            "amulet", AMULET_BASE_PREMIUM_IN_G,
            "staff", STAFF_BASE_PREMIUM_IN_G,
            "potion", POTION_BASE_PREMIUM_IN_G);

    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private PriceList() {
    }

    static BigDecimal basePremiumFor(Item item) {
        if (isComponent(item)) {
            return BigDecimal.valueOf(COMPONENT_BASE_PREMIUM_IN_G);
        }
        return BigDecimal.valueOf(MAIN_ITEM_BASE_PREMIUMS_IN_G.getOrDefault(item.type(), NOT_TARIFFED));
    }

    static BigDecimal insuranceValueFor(Item item) {
        if (isComponent(item)) {
            return BigDecimal.valueOf(COMPONENT_INSURANCE_VALUE_IN_G);
        }
        return BigDecimal.valueOf(
                MAIN_ITEM_INSURANCE_VALUES_IN_G.getOrDefault(item.type(), NOT_TARIFFED));
    }

    private static boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }
}
=== Percentage.java
import java.math.BigDecimal;

/**
 * A rate the MHPCO levies or grants, as a percentage of some amount.
 *
 * <p>Every MHPCO modifier — the item risk surcharges as well as the
 * policy-wide loyalty, first insurance and follow-up contract modifiers — is
 * expressed as a percentage of an amount. This is the one place that knows
 * what taking a percentage of an amount means, so the modifiers are left to
 * differ only in their rate and in which amount they are measured against.
 *
 * <p>The result is kept as a fraction: the MHPCO settles to whole G only once,
 * at the end of a calculation.
 */
record Percentage(int percent) {

    private static final BigDecimal HUNDRED_PERCENT = BigDecimal.valueOf(100);

    static Percentage of(int percent) {
        return new Percentage(percent);
    }

    /**
     * The part of {@code amount} this rate comes to, exactly.
     *
     * <p>Exact division is deliberate: MHPCO rates divide their amounts evenly,
     * and a rate that did not would be a tariff the MHPCO has not decided how
     * to settle rather than something to silently round away.
     */
    BigDecimal ofAmount(BigDecimal amount) {
        return amount.multiply(BigDecimal.valueOf(percent)).divide(HUNDRED_PERCENT);
    }
}
=== PremiumCalculator.java
import java.math.BigDecimal;
import java.util.List;

/**
 * Assembles the MHPCO premium for the items of a quote.
 *
 * <p>Knows that a premium is the policy base premium plus the risk surcharges
 * the insured items carry plus the policy-wide modifiers the customer's
 * standing earns plus the processing fee charged on every premium, and that
 * the intermediate amounts are kept as fractions until the premium is
 * settled to whole G. Defers what settling in the MHPCO's favour means to the
 * MHPCO's settlement rule.
 */
final class PremiumCalculator {

    private static final BigDecimal PROCESSING_FEE_IN_G = BigDecimal.valueOf(5);

    private PremiumCalculator() {
    }

    static int premiumFor(Customer customer, int precedingContracts, List<Item> items) {
        BigDecimal policyBasePremium = PolicyBasePremium.of(items);
        BigDecimal premium = policyBasePremium
                .add(RiskSurcharges.of(items))
                .add(PolicyModifiers.of(customer, precedingContracts, policyBasePremium))
                .add(PROCESSING_FEE_IN_G);
        return WholeG.premium(premium);
    }
}
=== RiskSurcharges.java
import java.math.BigDecimal;
import java.util.List;

/**
 * The item-specific risk surcharges the MHPCO levies on the items of a quote.
 *
 * <p>Holds the MHPCO's reading of the scope question: an item-specific
 * surcharge is a percentage of the base premium of the affected item, not of
 * the policy base premium. The surcharges of a quote are therefore the sum,
 * over its items, of every recognised risk that item carries. Defers which
 * risks exist and what each costs to the MHPCO's list of insurable risks.
 *
 * <p>Changes whenever the MHPCO revises how an item-specific surcharge is
 * measured or accumulated; knows nothing about the policy-wide modifiers
 * (loyalty, first insurance, follow-up contract), which apply to the policy
 * base premium.
 */
final class RiskSurcharges {

    private RiskSurcharges() {
    }

    static BigDecimal of(List<Item> items) {
        return items.stream()
                .map(RiskSurcharges::surchargesOn)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private static BigDecimal surchargesOn(Item item) {
        BigDecimal itemBasePremium = PriceList.basePremiumFor(item);
        return InsurableRisk.carriedBy(item).stream()
                .map(risk -> risk.surchargeRate().ofAmount(itemBasePremium))
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
=== PolicyBasePremium.java
import java.math.BigDecimal;
import java.util.List;
import java.util.stream.Collectors;

/**
 * The base premium the MHPCO tariffs a whole quote at.
 *
 * <p>Knows that the items of a quote are tariffed in groups of alike items and
 * that the policy base premium is the sum over those groups. Defers what a
 * group of alike items costs to the MHPCO's building block offer, and knows
 * nothing about the surcharges, discounts and the processing fee that turn a
 * base premium into a premium.
 *
 * <p>Holds the MHPCO's reading of "alike": items are alike when they are of
 * the same type, not merely of the same family. Two runes and a moonstone are
 * therefore two groups, not one group of gemstone-y things.
 */
final class PolicyBasePremium {

    private PolicyBasePremium() {
    }

    static BigDecimal of(List<Item> items) {
        return items.stream()
                .collect(Collectors.groupingBy(Item::type))
                .values().stream()
                .map(BuildingBlock::basePremiumFor)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}
=== WholeG.java
import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * The MHPCO's settlement rule: a calculation is kept as fractions throughout
 * and only its final amount is settled to whole G, always in the MHPCO's own
 * favour.
 *
 * <p>Favour has a direction, and the direction depends on which way the money
 * moves. On a premium, money the MHPCO receives, favour rounds up. On a
 * payout, money the MHPCO pays out, favour rounds down. The two are stated
 * together here so the asymmetry is visible rather than rediscovered.
 *
 * <p>Changes whenever the MHPCO revises how it settles fractions; knows
 * nothing about how any amount was arrived at.
 */
final class WholeG {

    private WholeG() {
    }

    /**
     * Settles a premium — money the MHPCO receives — so a fraction of a G
     * falls to the MHPCO.
     */
    static int premium(BigDecimal amount) {
        return amount.setScale(0, RoundingMode.CEILING).intValueExact();
    }

    /**
     * Settles a payout — money the MHPCO pays out — so a fraction of a G stays
     * with the MHPCO.
     */
    static int payout(BigDecimal amount) {
        return amount.setScale(0, RoundingMode.FLOOR).intValueExact();
    }
}
=== ScenarioLedger.java
import java.util.HashMap;
import java.util.Map;

/**
 * The running record the MHPCO carries from one step of a scenario to the
 * next.
 *
 * <p>Holds two readings of how the steps of a scenario bear on one another.
 * Every contract concluded before a step makes that step a follow-up
 * contract, so the ledger counts them as it goes. And a claim names the
 * policy it is made against by the zero-based index of the quote step that
 * wrote it, so the ledger files each policy under that index.
 *
 * <p>Changes whenever the MHPCO revises what one step of a scenario means for
 * the next; knows nothing about tariffs, payouts or the wire format.
 */
final class ScenarioLedger {

    private final Map<Integer, Policy> policiesByQuoteStep = new HashMap<>();
    private int concludedContracts;

    /**
     * Files the policy a quote step wrote under that step's index, and counts
     * the contract as concluded.
     */
    void recordPolicy(int quoteStepIndex, Policy policy) {
        policiesByQuoteStep.put(quoteStepIndex, policy);
        concludedContracts++;
    }

    /**
     * The policy a claim names by the index of the quote step that wrote it.
     */
    Policy policyWrittenBy(int quoteStepIndex) {
        return policiesByQuoteStep.get(quoteStepIndex);
    }

    /**
     * How many contracts the customer had already concluded in this scenario.
     */
    int concludedContracts() {
        return concludedContracts;
    }
}

